function verifyJWT(auth){
  const crypto = require('crypto');
  const SECRET = 'yavibot-dev-secret-change-me';
  if(!auth || !auth.startsWith('Bearer ')) return null;
  const parts = auth.slice(7).split('.');
  if(parts.length !== 3) return null;
  const [h,p,s] = parts;
  const b64 = b => Buffer.from(b).toString('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
  if(b64(crypto.createHmac('sha256', SECRET).update(h+'.'+p).digest()) !== s) return null;
  let c; try { c = JSON.parse(Buffer.from(p.replace(/-/g,'+').replace(/_/g,'/'),'base64').toString()); } catch(e){ return null; }
  if(c.exp && c.exp < Math.floor(Date.now()/1000)) return null;
  return c;
}

const { Client } = require('pg');
const claims = verifyJWT($json.headers.authorization || $json.headers.Authorization);
if(!claims) return [{ json:{ _status:401, _body:{ ok:false, error:{ code:'NO_AUTENTICADO', message:'Sesión no válida' } } } }];
if(claims.rol !== 'SUPERADMIN') return [{ json:{ _status:403, _body:{ ok:false, error:{ code:'SIN_PERMISO', message:'Solo el super administrador puede cargar datos' } } } }];

const registros = ($json.body || {}).registros || [];
if(!Array.isArray(registros) || registros.length === 0)
  return [{ json:{ _status:400, _body:{ ok:false, error:{ code:'VALIDACION', message:'El archivo no contiene registros' } } } }];

const ESTADOS = ['MATRICULADO','RETIRADO','REPROBADO','APROBADO'];
const MODS = ['PRESENCIAL','DUAL','EN LINEA','SEMIPRESENCIAL'];
const client = new Client({host:'postgres',port:5432,user:'yavibot',password:'yavibot_dev_2026',database:'yavibot'});
await client.connect();
try {
  const carreras = new Set((await client.query('SELECT id FROM carreras')).rows.map(r => Number(r.id)));
  const errores = [];
  const ced=[], nom=[], car=[], niv=[], par=[], mod=[], est=[], cor=[];
  const vistos = new Set();
  for(let i=0;i<registros.length;i++){
    const r = registros[i] || {};
    const cedula = String(r.cedula ?? '').trim().replace(/\D/g,'').padStart(10,'0');
    const nombres = String(r.nombres ?? '').trim();
    const carrera_id = Number(r.carrera_id);
    const nivel = String(r.nivel ?? '').trim().toUpperCase();
    const paralelo = String(r.paralelo ?? '').trim().toUpperCase();
    const modalidad = String(r.modalidad ?? 'PRESENCIAL').trim().toUpperCase();
    const estado = String(r.estado_matricula ?? '').trim().toUpperCase();
    const correo = String(r.correo ?? '').trim().toLowerCase();
    if(!/^[0-9]{10}$/.test(cedula)) { errores.push({fila:i+1, motivo:'Cédula inválida', valor:r.cedula}); continue; }
    if(vistos.has(cedula)) { errores.push({fila:i+1, motivo:'Cédula duplicada en el archivo', valor:cedula}); continue; }
    if(!nombres || !correo) { errores.push({fila:i+1, motivo:'Faltan nombres o correo', valor:cedula}); continue; }
    if(!carreras.has(carrera_id)) { errores.push({fila:i+1, motivo:'carrera_id inexistente', valor:carrera_id}); continue; }
    if(!ESTADOS.includes(estado)) { errores.push({fila:i+1, motivo:'estado_matricula no válido', valor:estado}); continue; }
    if(!MODS.includes(modalidad)) { errores.push({fila:i+1, motivo:'modalidad no válida', valor:modalidad}); continue; }
    vistos.add(cedula);
    ced.push(cedula); nom.push(nombres); car.push(carrera_id); niv.push(nivel);
    par.push(paralelo); mod.push(modalidad); est.push(estado); cor.push(correo);
  }

  let insertados=0, actualizados=0, omitidos=0;
  if(ced.length){
    const q = await client.query(
      `INSERT INTO estudiantes (cedula, nombres, carrera_id, nivel, paralelo, modalidad, estado_matricula, correo)
       SELECT * FROM unnest($1::varchar[], $2::varchar[], $3::bigint[], $4::varchar[], $5::varchar[], $6::varchar[], $7::varchar[], $8::varchar[])
       ON CONFLICT (cedula) DO UPDATE SET
         nombres=EXCLUDED.nombres, carrera_id=EXCLUDED.carrera_id, nivel=EXCLUDED.nivel, paralelo=EXCLUDED.paralelo,
         modalidad=EXCLUDED.modalidad, estado_matricula=EXCLUDED.estado_matricula, correo=EXCLUDED.correo, actualizado_en=now()
       WHERE (estudiantes.nombres, estudiantes.carrera_id, estudiantes.nivel, estudiantes.paralelo,
              estudiantes.modalidad, estudiantes.estado_matricula, estudiantes.correo)
         IS DISTINCT FROM (EXCLUDED.nombres, EXCLUDED.carrera_id, EXCLUDED.nivel, EXCLUDED.paralelo,
              EXCLUDED.modalidad, EXCLUDED.estado_matricula, EXCLUDED.correo)
       RETURNING (xmax = 0) AS inserted`,
      [ced, nom, car, niv, par, mod, est, cor]);
    insertados = q.rows.filter(r => r.inserted).length;
    actualizados = q.rows.length - insertados;
    omitidos = ced.length - q.rows.length;
  }

  await client.query(
    'INSERT INTO importaciones (tipo, archivo, insertados, actualizados, omitidos, errores, usuario_ref) VALUES ($1,$2,$3,$4,$5,$6,$7)',
    ['estudiantes', String(($json.body||{}).archivo || 'carga'), insertados, actualizados, omitidos, JSON.stringify(errores.slice(0,200)), String(claims.sub)]);

  return [{ json:{ _status:200, _body:{ ok:true, data:{ insertados, actualizados, omitidos, errores: errores.length, total: registros.length, detalleErrores: errores.slice(0,50) } } } }];
} finally { await client.end(); }
